-- ---------------------------------------------------------------------------
-- mod-item-upgrade : items and NPC (WORLD database)
--
-- 1. The five power tokens (801050-801054), the currency of ranks 4 to 20.
-- 2. Their item_dbc rows (the SQL override of the server's Item.dbc: without
--    them, ObjectMgr::LoadItemTemplates simply IGNORES any item missing from
--    Item.dbc). The client needs those rows too: see tools/patch_item_dbc.py.
-- 3. The upgrade master, NPC 200003 (C++ script npc_item_upgrade), and its
--    three spawns: Orgrimmar (Valley of Strength), Dalaran, Stormwind (Trade
--    District). Spawn guids are taken after the highest existing one.
--
-- Item names are in French, as is the rest of this fork's in-game text.
-- README section 6.13 shows how to rename them.
--
-- Idempotent: replayable without creating duplicates.
-- ---------------------------------------------------------------------------

SET NAMES utf8mb4;

-- --- Power tokens ----------------------------------------------------------
DELETE FROM `item_template` WHERE `entry` BETWEEN 801050 AND 801054;
